//
//  ThirdPartyLicensesWindow.swift
//  Moonlight for macOS
//
//  The third-party licenses window: a searchable list of what is really in the app (name, version, license id) and the
//  license text of the selected one, selectable in a monospaced font. The data is ThirdPartyLicenses.json, generated by
//  scripts/generate_third_party_licenses.py from the license files of the dependencies themselves.
//

import AppKit
import SwiftUI

struct ThirdPartyLicenseData: Decodable {
  struct License: Decodable {
    let name: String
    let text: String
  }
  struct Dependency: Decodable, Identifiable {
    let id: String
    let name: String
    let version: String
    let spdx: String
    let url: String
    let kind: String
    let license: String
    let copyright: [String]
    let note: String?
    let notice: String?
  }

  let licenses: [String: License]
  let dependencies: [Dependency]

  static func load() -> ThirdPartyLicenseData? {
    guard let url = Bundle.main.url(forResource: "ThirdPartyLicenses", withExtension: "json"),
      let data = try? Data(contentsOf: url)
    else { return nil }
    return try? JSONDecoder().decode(ThirdPartyLicenseData.self, from: data)
  }
}

struct ThirdPartyLicensesView: View {
  let data: ThirdPartyLicenseData
  @ObservedObject private var languageManager = LanguageManager.shared
  @State private var query: String
  @State private var selection: String?

  init(data: ThirdPartyLicenseData, initialSelection: String? = nil, initialQuery: String = "") {
    self.data = data
    _query = State(initialValue: initialQuery)
    _selection = State(initialValue: initialSelection)
  }

  private var filtered: [ThirdPartyLicenseData.Dependency] {
    let q = query.trimmingCharacters(in: .whitespaces).lowercased()
    guard !q.isEmpty else { return data.dependencies }
    return data.dependencies.filter {
      $0.name.lowercased().contains(q) || $0.spdx.lowercased().contains(q)
        || $0.copyright.contains { $0.lowercased().contains(q) }
    }
  }

  private var selected: ThirdPartyLicenseData.Dependency? {
    data.dependencies.first { $0.id == (selection ?? filtered.first?.id) }
  }

  var body: some View {
    HSplitView {
      VStack(spacing: 0) {
        HStack(spacing: 6) {
          Image(systemName: "magnifyingglass").foregroundStyle(.secondary)
          TextField(languageManager.localize("Search"), text: $query)
            .textFieldStyle(.plain)
          if !query.isEmpty {
            Button { query = "" } label: { Image(systemName: "xmark.circle.fill") }
              .buttonStyle(.plain).foregroundStyle(.secondary)
          }
        }
        .padding(.horizontal, 10).padding(.vertical, 7)
        .background(RoundedRectangle(cornerRadius: 7, style: .continuous).fill(Color(nsColor: .quaternaryLabelColor).opacity(0.5)))
        .padding(10)
        List(selection: Binding(get: { selection ?? filtered.first?.id }, set: { selection = $0 })) {
          ForEach(filtered) { dep in
            VStack(alignment: .leading, spacing: 2) {
              Text(dep.name).font(.body.weight(.medium)).lineLimit(1)
              Text(rowDetail(dep)).font(.caption).foregroundStyle(.secondary).lineLimit(1)
            }
            .padding(.vertical, 2)
            .tag(dep.id)
          }
        }
        .listStyle(.sidebar)
      }
      .frame(minWidth: 230, idealWidth: 250, maxWidth: 260)

      Group {
        if let dep = selected { detail(dep) } else {
          Text(languageManager.localize("No matches")).foregroundStyle(.secondary)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
      }
      .frame(minWidth: 460, idealWidth: 600)
    }
  }

  private func rowDetail(_ dep: ThirdPartyLicenseData.Dependency) -> String {
    dep.spdx == "NOASSERTION" ? dep.version : "\(dep.version) · \(dep.spdx)"
  }

  private func kindLabel(_ kind: String) -> String {
    let key: String
    if kind.hasPrefix("static library") { key = "Static library" }
    else if kind.hasPrefix("framework") { key = "Framework" }
    else if kind.hasPrefix("data") { key = "Data" }
    else { key = "Source in the app" }
    return languageManager.localize(key)
  }

  @ViewBuilder
  private func detail(_ dep: ThirdPartyLicenseData.Dependency) -> some View {
    let license = data.licenses[dep.license]
    ScrollView {
      VStack(alignment: .leading, spacing: 14) {
        VStack(alignment: .leading, spacing: 4) {
          Text(dep.name).font(.title2.weight(.semibold))
          HStack(spacing: 8) {
            Text(dep.version).foregroundStyle(.secondary)
            if dep.spdx != "NOASSERTION" {
              Text(dep.spdx)
                .font(.caption.weight(.semibold))
                .padding(.horizontal, 7).padding(.vertical, 2)
                .background(Capsule().fill(Color.accentColor.opacity(0.16)))
            }
            Text(kindLabel(dep.kind)).foregroundStyle(.secondary)
          }
          .font(.callout)
          if let url = URL(string: dep.url), !dep.url.isEmpty {
            Link(dep.url, destination: url).font(.callout)
          }
        }
        if !dep.copyright.isEmpty {
          VStack(alignment: .leading, spacing: 2) {
            ForEach(Array(dep.copyright.enumerated()), id: \.offset) { _, line in
              Text(line).textSelection(.enabled)
            }
          }
          .font(.callout)
        }
        if let note = dep.note {
          Text(note).font(.callout).foregroundStyle(.secondary).textSelection(.enabled)
        }
        if let notice = dep.notice {
          Text(notice).font(.callout).foregroundStyle(.secondary).textSelection(.enabled)
        }
        if let license {
          Divider()
          Text(license.name).font(.headline)
          Text(verbatim: license.text)
            .font(.system(size: 11, design: .monospaced))
            .textSelection(.enabled)
            .frame(maxWidth: .infinity, alignment: .leading)
        }
      }
      .padding(20)
      .frame(maxWidth: .infinity, alignment: .leading)
    }
    .id(dep.id)
  }
}

enum ThirdPartyLicensesWindow {
  private static var window: NSWindow?

  /// Shows the window (one at a time). Returns false when the data is not in the bundle.
  @discardableResult
  static func show() -> Bool {
    if let window {
      window.makeKeyAndOrderFront(nil)
      return true
    }
    guard let data = ThirdPartyLicenseData.load() else { return false }
    let host = NSHostingController(rootView: ThirdPartyLicensesView(data: data))
    let window = NSWindow(contentViewController: host)
    window.title = LanguageManager.shared.localize("Third-Party Licenses")
    window.styleMask = [.titled, .closable, .resizable, .miniaturizable]
    window.setContentSize(NSSize(width: 860, height: 560))
    window.minSize = NSSize(width: 680, height: 380)
    window.isReleasedWhenClosed = false
    window.setFrameAutosaveName("ThirdPartyLicensesWindow")
    window.center()
    NotificationCenter.default.addObserver(forName: NSWindow.willCloseNotification, object: window, queue: .main) { _ in
      Self.window = nil
    }
    Self.window = window
    window.makeKeyAndOrderFront(nil)
    return true
  }
}
